const b = ($input.first().json.body) || $input.first().json;
const bmr = 10 * b.weightKg + 6.25 * b.heightCm - 5 * b.age + (b.sex === 'MALE' ? 5 : -161);
const mult = { SEDENTARY: 1.2, LIGHT: 1.375, MODERATE: 1.55, ACTIVE: 1.725, VERY_ACTIVE: 1.9 }[b.activityLevel] ?? 1.2;
const tdee = bmr * mult;
const daily = b.goal === 'LOSE' ? tdee * 0.85 : b.goal === 'GAIN' ? tdee * 1.15 : tdee;
const proteinG = b.weightKg * 1.8;
const fatG = daily * 0.25 / 9;
const carbsG = (daily - proteinG * 4 - fatG * 9) / 4;
const r = (v) => Math.round(v * 10) / 10;
return [{ json: {
  bmr: r(bmr),
  tdee: r(tdee),
  dailyCalories: r(daily),
  proteinG: r(proteinG),
  fatG: r(fatG),
  carbsG: r(Math.max(carbsG, 0))
} }];
